cd /app && cat > discount.py << 'EOF'
"""Order pricing helpers."""


def apply_discount(price, percent):
    """Return `price` reduced by `percent` percent."""
    # Apply tiered discount logic
    if price >= 200:
        discount_rate = percent
    elif price >= 100:
        discount_rate = percent + 5
    else:
        discount_rate = percent

    return price * (1 - discount_rate / 100)
EOF

