cat > /app/discount.py << 'EOF'
"""Order pricing helpers."""


def apply_discount(price, percent):
    """Return `price` reduced by `percent` percent."""
    discount_rate = percent / 100

    # Apply an extra 5% discount if percent is 10
    if percent == 10:
        discount_rate += 0.05

    return price * (1 - discount_rate)
EOF

