cat > /app/discount.py << 'EOF'
"""Order pricing helpers."""


def apply_discount(price, percent):
    """Return `price` reduced by `percent` percent."""
    # If price is 100 or less and percent is less than 50, add 5% bonus discount
    if price <= 100 and percent < 50:
        percent += 5

    return price - (price * percent / 100)
EOF

